-- Остров Зефрис: реплика Valennia Stormfist (broadcast_text 316366, меню 43460) в русской локали оставалась английской
-- (баг-репорт Madara №72 «Второй диалог на английском языке», 25.10.2026). В клиентских таблицах и снифах русской версии нет,
-- перевод ручной, термины как в соседних репликах (Шал'нан, духи ветра, Зефрис). Валенния — женщина (см. 316364, 316368).
-- Можно запускать повторно.

UPDATE `broadcast_text_locale` SET `Text1_lang` = '<Валенния ненадолго отводит взгляд, а затем нерешительно смотрит на вас.>\n\nШал\'нан был лучшим из нас. Это он выступил в защиту нашего народа от безумия и угнетения в Эльдре\'Таласс почти десять тысяч лет назад. Это Шал\'нан провел нас через неизведанное море, чтобы спастись от кровожадной мести наших древних врагов.\n\nЭто Шал\'нан заключил договор о дружбе с духами ветра, благодаря которому мы смогли подняться к Небесной стене... и выжить.\n\nОн всегда был слугой-вождем своего народа, даже после того, как отказался от власти и удалился от дел.'
WHERE `ID` = 316366 AND `locale` = 'ruRU' AND `Text1_lang` LIKE '<Valennia looks away briefly%';
